import{_ as e,o as t,c as r,U as i}from"./chunks/framework.e625a6bf.js";const d=JSON.parse('{"title":"AI来了，同事们的效率为什么差这么多？","description":"","frontmatter":{"title":"AI来了，同事们的效率为什么差这么多？","date":"2026/04/30 12:38:00","summary":"最近在团队里，我观察到一个很有意思的现象：同样是使用AI辅助开发，不同同事的使用效果却差别明显。有人效率明显提升，有人却几乎没什么变化，甚至偶尔还会多花一些时间。","config":{"show":true,"top":false,"dir":true,"dirTag":["h3","h4","h5"],"tag":["info","ai","tool"],"valine":true,"valineId":null},"password":false,"outline":[3,5]},"headers":[],"relativePath":"views/blog/ai/2026-0430-AI来了同事们的效率为什么差这么多.md","filePath":"views/blog/ai/2026-0430-AI来了同事们的效率为什么差这么多.md"}'),o={name:"views/blog/ai/2026-0430-AI来了同事们的效率为什么差这么多.md"};function l(n,a,p,s,A,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h6 id="原文-掘金" tabindex="-1">原文 <a href="https://juejin.cn/post/7628080756385398824" target="_blank" rel="noreferrer">掘金</a> <a class="header-anchor" href="#原文-掘金" aria-label="Permalink to &quot;原文 [掘金](https://juejin.cn/post/7628080756385398824)&quot;">​</a></h6><p>最近在团队里，我观察到一个很有意思的现象：同样是使用AI辅助开发，不同同事的使用效果却差别明显。有人效率明显提升，有人却几乎没什么变化，甚至偶尔还会多花一些时间。这让我开始思考：<strong>AI究竟是如何影响我们日常工作的？是工具本身的问题，还是使用方式的差异？</strong></p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260430-123801-09d16927.awebp" alt="How AI Coding Assistants Will Change Developer Jobs by 2026"></p><h3 id="一、a同学-效率显著提升-形成良性循环" tabindex="-1">一、A同学：效率显著提升，形成良性循环 <a class="header-anchor" href="#一、a同学-效率显著提升-形成良性循环" aria-label="Permalink to &quot;一、A同学：效率显著提升，形成良性循环&quot;">​</a></h3><p>A同学负责的车机环境搭建和平台化项目迁移，是团队里公认的“重活”。以前每次做平台迁移，都需要手动调整大量的配置文件、适配不同硬件的接口调用、修改模块之间的依赖关系，经常耗费大量时间。</p><p>在使用AI之后，他的整体工时直接减少了一半。比如在迁移某个核心模块时，AI帮他快速生成了基础的适配代码框架，他只需要重点检查模块间的调用链路是否正确、参数传递是否一致，就大大加快了进度。解决Bug时也高效了很多——以前一天大概能处理10个Bug，现在同样的Bug数量，他通常两个小时左右就能搞定。</p><p>最明显的变化是Bug率降低了大约70%。代码评审时，以前经常被指出接口不兼容、边界条件处理不当等问题，现在这类返工明显减少。A同学自己说，AI最有价值的地方在于帮他快速验证一些常规逻辑，让他有时间去思考整体架构：比如如何让新旧平台之间的数据流转更顺畅，如何减少重复代码。</p><p>节省下来的时间，他用来学习新的车机开发框架、研究更优雅的模块解耦方式，甚至开始尝试一些性能优化的小技巧。这样就形成了一个良性循环——效率越高，能投入的学习时间越多，能力提升得越快，工作也越来越得心应手。</p><h3 id="二、b同学-效率变化不大-甚至偶尔更慢" tabindex="-1">二、B同学：效率变化不大，甚至偶尔更慢 <a class="header-anchor" href="#二、b同学-效率变化不大-甚至偶尔更慢" aria-label="Permalink to &quot;二、B同学：效率变化不大，甚至偶尔更慢&quot;">​</a></h3><p>B同学同样承担了部分迁移和Bug修复工作，他也非常积极地使用AI工具。但实际情况是，他的整体效率提升并不明显，有时候处理一个Bug反而比以前花的时间更长。</p><p>B同学排查Bug时，习惯先盯着当前的日志输出和报错方法，很少去完整梳理从入口到当前节点的整个调用链路。时间一长，他对自己前几天写的代码就有些模糊，经常会自言自语：“这个方法当时为什么要这么写？” 一个Bug修改完，常常又引发新的问题——比如改动了某个接口参数，导致下游模块的调用失败；修复了下游问题，又把上游的边界条件搞乱，来回拉扯。</p><p>在使用AI时，他经常被AI给出的多种可能原因和修改建议带得有些迷失。一会儿按照AI的提示调整日志打印方式，一会儿又尝试修改调用顺序，最后自己也很难判断哪个方案最合适。有一次在代码评审会上，评审老师问他某处改动的原因，他坦诚地说：“<strong>是AI建议这么改的，当时我觉得它分析得挺有道理。</strong>” 当时都快气吐血了，能这么回答吗？？？</p><h3 id="三、ai提升效率-关键在于人" tabindex="-1">三、AI提升效率，关键在于人 <a class="header-anchor" href="#三、ai提升效率-关键在于人" aria-label="Permalink to &quot;三、AI提升效率，关键在于人&quot;">​</a></h3><p>通过A和B两位同学的对比，我越来越觉得：<strong>AI能不能真正帮我们提升效率，核心不在于工具本身有多聪明，而在于使用者是否有清晰的思路和扎实的工作习惯。</strong></p><p>有一定基础、思考逻辑清楚的人，使用AI就像给原本就跑得稳的人加了一个助力，速度会越来越快；如果对代码的整体理解还不够深入，只是把AI当成“万能解答器”，就容易陷入被动跟随的状态，花更多时间在反复验证和纠错上。</p><p>当然，这并不意味着B同学能力不足。他工作态度很认真，抗压能力强，经常主动加班，但需要别人帮助才能完成任务。只是AI在一定程度上放大了每个人原有的工作习惯差异。</p><p>其实类似的现象在很多开发团队里都存在。有的开发者用AI后能快速完成重复性的接口适配，把精力放在系统优化上；有的则因为过度依赖，代码评审时发现很多地方需要大幅调整。最终，受益最大的往往是那些本来就善于思考和总结的人。</p><h3 id="四、正确使用ai-辅助-而非依赖" tabindex="-1">四、正确使用AI：辅助，而非依赖 <a class="header-anchor" href="#四、正确使用ai-辅助-而非依赖" aria-label="Permalink to &quot;四、正确使用AI：辅助，而非依赖&quot;">​</a></h3><p>AI不是来取代程序员的，而是来辅助我们更好地工作。它可以帮我们处理大量重复的 boilerplate 代码、提供参考思路、加速常规任务的验证，但最终的决策、质量把控和责任承担，还是要靠我们自己。</p><p>作为程序员，我们最宝贵的其实是那份务实和勤奋。在AI时代，更聪明的做法是学会善用AI，把它当作提升自身能力的工具：</p><ul><li>先自己尝试思考和实现核心逻辑，再用AI辅助优化细节或验证方案；</li><li>始终保持对代码整体流程的理解，不要跳过必要的审查和测试；</li><li>把节省出来的时间，用来学习新知识、打磨代码习惯，或者留给家人和生活。</li></ul><p>我们努力工作，最终还是希望生活能越来越平衡、越来越有温度。AI只是工具，它可以让我们少做一些机械重复的事，却无法代替我们去思考、去创造、去感受生活的美好。</p><p>希望每一位程序员都能找到适合自己的使用方式，让AI真正成为助力，而不是负担。把多出来的时间，用在让自己和身边的人更快乐的事情上，才是最值得的。</p><p>大家当个乐子看一下就行了，我个人片面的看法是，B同学主要是方法论暂时出了点问题——也许哪天他掌握了正确的梳理流程和使用AI的方式，说不定也能变成效率非常高的人呢。</p>',24)])])}const u=e(o,[["render",l]]);export{d as __pageData,u as default};
